import randomimport stringimport jwtfrom datetime import datetime, timedeltafrom odoo import api, fields, models, _, toolsfrom odoo.exceptions import UserErrorimport logging_logger = logging.getLogger(__name__)class SaleAgent(models.Model):    _name = "sale.agent"    _inherit = ['mail.thread', 'mail.activity.mixin']    _rec_name = "full_name"    _description = "Sale Agent Details"    email = fields.Char(string="Email")    password = fields.Char(string="Password")    full_name = fields.Char(string="Full Name")    nic = fields.Char(string="NIC")    mobile = fields.Char(string="Mobile NO")    agent_id = fields.Char(string="Agent ID")    # secret_key = fields.Char(string="Secret Key")    crm_team_id = fields.Many2one(comodel_name="crm.team", string="Sales Team")    company_id = fields.Many2one(comodel_name='res.company', string='Company')    user_id = fields.Many2one(comodel_name='res.users', string='User', required=True)    def generate_registration_token(self):        """Generate a JWT registration token valid for 48 hours."""        self.ensure_one()        jwt_secret = 'homelands-web-app-for-sale-agent'        payload = {            'agent_id': self.id,            'email': self.user_id.login if self.user_id and self.user_id.login else '',            'purpose': 'registration',            'exp': datetime.utcnow() + timedelta(hours=48),            'iat': datetime.utcnow()        }        token = jwt.encode(payload, jwt_secret, algorithm='HS256')        return token    def generate_sequence(self):        length = 6        characters = string.ascii_letters + string.digits        sequence = ''.join(random.choice(characters) for i in range(length))        return sequence    @api.model    def create(self, vals):        # if not vals.get('secret_key'):        #     vals['secret_key'] = self.generate_sequence()        sale_agent = super(SaleAgent, self).create(vals)        sale_agent._update_crm_team_members()        return sale_agent    def write(self, vals):        res = super(SaleAgent, self).write(vals)        self._update_crm_team_members()        return res    def name_get(self):        res = []        for sale_agent in self:            res.append((sale_agent.id, '%s (%s)' % (sale_agent.full_name, sale_agent.emp_id)))        return res    def action_send_agent_invitation(self):        for agent in self:            _logger.info("Starting agent invitation process for Agent ID: %s", agent.id)            # Validate            if not agent.user_id or not agent.user_id.login:                raise UserError(...)            try:                # Generate JWT token                registration_token = agent.generate_registration_token()                # Get portal URL                base_url = 'https://portal.odoo.homelands.lk'                # Create registration link                registration_link = f"{base_url}/signup?token={registration_token}"                _logger.info(registration_link)                # Send with context                ctx = {                    'registration_link': registration_link,                    'agent_name': agent.full_name,                    'agent_email': agent.user_id.login,                }                template = self.env.ref('vkd_property_management.sale_agent_invitation_email_template')                template.with_context(ctx).send_mail(agent.id, force_send=True)                # Log to chatter                agent.message_post()            except Exception as e:                _logger.error("Failed to send invitation", exc_info=True)                raise UserError(...)    def _update_crm_team_members(self):        for agent in self:            if agent.crm_team_id and agent.user_id:                if agent.user_id.id not in agent.crm_team_id.member_ids.ids:                    agent.crm_team_id.write({                        'member_ids': [(4, agent.user_id.id)]                    })